// HM4 (Stride-Pattern) war als vierte Subaxis geplant, wurde aber nie durch einen
// Wrapper getragen (kein `axis_tag` referenziert sie) — toter Tag entfernt.
// Ein permutierbarer Stride-*Wert* wuerde AllLayouts (5 golden-320-Werte) / Gate-1
// brechen; die IMC-Runtime-Heuristik bleibt compile-time-Doku-Backlog
// (docs/architecture/16_axis_05_imc_runtime_heuristik.md).

/// SPACE-Seite des T16-Kern-Trade-offs (Space-Effizienz @ Ziel-FPR): strukturelles Bit-Budget der REALEN
/// Bitmap, compile-time aus kBitmapBytes abgeleitet (= sizeof(bitmap_)*8). Static-constexpr-Descriptor analog
/// probe_multiplicity() — KEIN Datenmember (Layout/trivially_copyable/ABI unberuehrt), KEIN neuer Achsenwert
/// (AllFilters bleibt 4 → golden-320 4x4x5x4 + Gate-1-Produkt unberuehrt), KEIN POD-Feld (1416 unberuehrt).
[[nodiscard]] static constexpr std::size_t filter_bit_capacity() noexcept { return kBitmapBytes * 8u; }
/// bits/key bei key_count gespeicherten Keys — spiegelt composable/ louds_sparse_filter_store::bits_per_key()
/// (bit_size/key_count, key_count==0 → 0.0). key_count aus dem realen Fuellstand (tier_fill_level, Observer-POD).
[[nodiscard]] static constexpr double bits_per_key(std::size_t key_count) noexcept {
    return key_count ? static_cast<double>(filter_bit_capacity()) / static_cast<double>(key_count) : 0.0;
}

/// SPACE-Seite des T16-Kern-Trade-offs: strukturelles Bit-Budget der REALEN Bucket-Tabelle (kBuckets ×
/// kSlotsPerBucket 1-Byte-Fingerprints = sizeof(table_)*8), compile-time. Static-constexpr-Descriptor analog
/// probe_multiplicity() — kein Datenmember, kein neuer Achsenwert, kein POD-Feld (golden-320/Gate-1/1416 neutral).
[[nodiscard]] static constexpr std::size_t filter_bit_capacity() noexcept { return kBuckets * kSlotsPerBucket * 8u; }
/// bits/key bei key_count Keys — spiegelt composable/ bits_per_key() (key_count==0 → 0.0).
[[nodiscard]] static constexpr double bits_per_key(std::size_t key_count) noexcept {
    return key_count ? static_cast<double>(filter_bit_capacity()) / static_cast<double>(key_count) : 0.0;
}

/// SPACE-Seite des T16-Kern-Trade-offs: strukturelles Bit-Budget der REALEN Slot-Tabelle (kSlots 1-Byte-Slots =
/// sizeof(table_)*8), compile-time. Static-constexpr-Descriptor analog probe_multiplicity() — kein Datenmember,
/// kein neuer Achsenwert, kein POD-Feld (golden-320/Gate-1/1416 neutral).
[[nodiscard]] static constexpr std::size_t filter_bit_capacity() noexcept { return kSlots * 8u; }
/// bits/key bei key_count Keys — spiegelt composable/ bits_per_key() (key_count==0 → 0.0).
[[nodiscard]] static constexpr double bits_per_key(std::size_t key_count) noexcept {
    return key_count ? static_cast<double>(filter_bit_capacity()) / static_cast<double>(key_count) : 0.0;
}

/// SPACE-Seite des T16-Kern-Trade-offs: strukturelles Bit-Budget der REALEN Knoten-Bitmap (kNodeBytes =
/// sizeof(nodes_)*8), compile-time. Static-constexpr-Descriptor analog probe_multiplicity() — kein Datenmember,
/// kein neuer Achsenwert, kein POD-Feld (golden-320/Gate-1/1416 neutral).
[[nodiscard]] static constexpr std::size_t filter_bit_capacity() noexcept { return kNodeBytes * 8u; }
/// bits/key bei key_count Keys — spiegelt composable/ bits_per_key() (key_count==0 → 0.0).
[[nodiscard]] static constexpr double bits_per_key(std::size_t key_count) noexcept {
    return key_count ? static_cast<double>(filter_bit_capacity()) / static_cast<double>(key_count) : 0.0;
}

